CREATE TABLE IF NOT EXISTS catalog_versions (
  version TEXT PRIMARY KEY,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  item_count INT NOT NULL DEFAULT 0,
  notes TEXT
);

CREATE TABLE IF NOT EXISTS catalog_categories (
  id SERIAL PRIMARY KEY,
  name_en TEXT NOT NULL UNIQUE,
  name_ur TEXT NOT NULL DEFAULT '',
  sort_order INT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS catalog_items (
  sku TEXT PRIMARY KEY,
  category TEXT NOT NULL,
  brand TEXT NOT NULL,
  name_en TEXT NOT NULL,
  name_ur TEXT NOT NULL DEFAULT '',
  model_compatibility TEXT,
  colors JSONB NOT NULL DEFAULT '[]'::jsonb,
  variants JSONB NOT NULL DEFAULT '[]'::jsonb,
  purchase_price_est INT NOT NULL DEFAULT 0 CHECK (purchase_price_est >= 0),
  sale_price_est INT NOT NULL DEFAULT 0 CHECK (sale_price_est >= 0),
  min_price INT NOT NULL DEFAULT 0 CHECK (min_price >= 0),
  unit TEXT NOT NULL DEFAULT 'piece',
  barcode TEXT UNIQUE,
  is_custom BOOLEAN NOT NULL DEFAULT FALSE,
  estimated BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_catalog_items_category ON catalog_items (category);
CREATE INDEX IF NOT EXISTS idx_catalog_items_brand ON catalog_items (brand);
CREATE INDEX IF NOT EXISTS idx_catalog_items_name ON catalog_items (name_en);

CREATE TABLE IF NOT EXISTS catalog_item_models (
  sku TEXT NOT NULL REFERENCES catalog_items (sku) ON DELETE CASCADE,
  device_brand TEXT NOT NULL,
  device_model TEXT NOT NULL,
  PRIMARY KEY (sku, device_brand, device_model)
);

CREATE TABLE IF NOT EXISTS barcode_links (
  barcode TEXT PRIMARY KEY,
  sku TEXT NOT NULL REFERENCES catalog_items (sku) ON DELETE CASCADE,
  linked_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS catalog_stock (
  sku TEXT PRIMARY KEY REFERENCES catalog_items (sku) ON DELETE CASCADE,
  quantity INT NOT NULL DEFAULT 0 CHECK (quantity >= 0),
  last_purchase_price INT,
  last_supplier TEXT,
  last_stock_date TIMESTAMPTZ,
  low_stock_threshold INT NOT NULL DEFAULT 5
);

CREATE TABLE IF NOT EXISTS stock_counts (
  id SERIAL PRIMARY KEY,
  sku TEXT NOT NULL REFERENCES catalog_items (sku) ON DELETE CASCADE,
  counted_qty INT NOT NULL,
  system_qty INT NOT NULL,
  difference INT NOT NULL,
  note TEXT,
  counted_by TEXT,
  counted_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_stock_counts_sku ON stock_counts (sku);

